int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int N, K, Q;
    scanf("%d %d %d", &N, &K, &Q);
    int A[N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }

    int M = N - K + 1;
    int mins[M];

    // sliding window minimum
    for (int i = 0; i <= N - K; i++) {
        int min_val = A[i];
        for (int j = i; j < i + K; j++) {
            if (A[j] < min_val) min_val = A[j];
        }
        mins[i] = min_val;
    }

    qsort(mins, M, sizeof(int), cmp);

    int ans = 1e9;
    for (int i = 0; i + Q - 1 < M; i++) {
        int diff = mins[i + Q - 1] - mins[i];
        if (diff < ans) ans = diff;
    }

    printf("%d\n", ans);
    return 0;
}

