typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, K, Q;
    if (scanf("%d %d %d", &N, &K, &Q) != 3) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    ll *vals = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) vals[i] = A[i];
    qsort(vals, N, sizeof(ll), cmp_ll);

    ll ans = (1LL << 62);

    ll *cand = (ll *)malloc(sizeof(ll) * N);
    ll *seg = (ll *)malloc(sizeof(ll) * N);

    for (int vi = 0; vi < N; vi++) {
        ll mn = vals[vi];
        int csz = 0;

        int i = 0;
        while (i < N) {
            if (A[i] < mn) {
                i++;
                continue;
            }

            int len = 0;
            while (i < N && A[i] >= mn) {
                seg[len++] = A[i];
                i++;
            }

            if (len >= K) {
                qsort(seg, len, sizeof(ll), cmp_ll);
                int take = len - K + 1;
                for (int t = 0; t < take; t++) {
                    cand[csz++] = seg[t];
                }
            }
        }

        if (csz >= Q) {
            qsort(cand, csz, sizeof(ll), cmp_ll);
            ll diff = cand[Q - 1] - cand[0];
            if (diff < ans) ans = diff;
        }
    }

    printf("%lld\n", ans);

    free(A);
    free(vals);
    free(cand);
    free(seg);
    return 0;
}

