    cin >> N >> K >> Q;
    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    vector<long long> vals = A;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    const long long INF = (1LL << 60);
    long long ans = INF;

    for (long long low : vals) {
        vector<long long> candidates;

        int i = 0;
        while (i < N) {
            if (A[i] < low) {
                ++i;
                continue;
            }
            int j = i;
            while (j < N && A[j] >= low) ++j;

            vector<long long> seg;
            for (int t = i; t < j; ++t) seg.push_back(A[t]);
            sort(seg.begin(), seg.end());

            int len = j - i;
            int cnt = len - K + 1; // how many removals can be done inside this segment
            for (int t = 0; t < cnt; ++t) {
                candidates.push_back(seg[t]);
            }

            i = j;
        }

        if ((int)candidates.size() < Q) continue;
        sort(candidates.begin(), candidates.end());
        ans = min(ans, candidates[Q - 1] - low);
    }

    cout << ans << '\n';
    return 0;
