public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());

        int[] A = new int[N];
        Integer[] idx = new Integer[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            A[i] = Integer.parseInt(st.nextToken());
            idx[i] = i;
        }

        // Sort indices by their value
        Arrays.sort(idx, Comparator.comparingInt(i -> A[i]));

        // Binary search on answer
        int left = 0, right = 1_000_000_000, ans = right;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (canAchieve(A, idx, N, K, Q, mid)) {
                ans = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        System.out.println(ans);
    }

    static boolean canAchieve(int[] A, Integer[] idx, int N, int K, int Q, int diff) {
        // Sliding window over sorted values: check if there exists Q elements
        // with max-min <= diff that can be removed
        for (int i = 0; i + Q - 1 < N; i++) {
            if (A[idx[i + Q - 1]] - A[idx[i]] > diff) continue;
            // Check if these Q indices can be removed in order
            if (canRemove(idx, i, i + Q - 1, N, K)) {
                return true;
            }
        }
        return false;
    }

    static boolean canRemove(Integer[] sortedIdx, int l, int r, int N, int K) {
        // Collect the actual indices to remove
        List<Integer> positions = new ArrayList<>();
        for (int i = l; i <= r; i++) {
            positions.add(sortedIdx[i]);
        }
        Collections.sort(positions);

        // Greedy: we remove from left to right.
        // When picking an element at position p, we must have at least K-1 elements
        // after previous removed one that are not removed yet, to form the window.
        // Equivalent check: For each selected index, the number of available 
        // elements before it must be at least (number already removed) * (K-1)?
        // Simpler simulation:

        // We simulate removal: we have a boolean array or use a data structure.
        // Since Q <= N and K <= N, we can simulate greedily with a pointer.
        boolean[] removed = new boolean[N];
        int removedCount = 0;
        int ptr = 0; // pointer in positions list
        int idx = 0; // pointer in array

        while (ptr < positions.size()) {
            // Find next removable element at positions[ptr]
            int target = positions.get(ptr);
            // Count available elements in window of size K starting at some point
            // We need to find a window containing target where all other K-1 elements
            // are not yet removed.
            boolean found = false;
            int start = Math.max(0, target - K + 1);
            for (int s = start; s <= target; s++) {
                if (s + K > N) break;
                boolean ok = true;
                for (int j = s; j < s + K; j++) {
                    if (j == target) continue;
                    if (removed[j]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    // remove target
                    removed[target] = true;
                    removedCount++;
                    ptr++;
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
}

