public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), K = sc.nextInt(), Q = sc.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) A[i] = sc.nextInt();

        int[] sorted = A.clone();
        Arrays.sort(sorted);
        int ans = sorted[N-1] - sorted[0];

        for (int i = 0; i < N; i++) {
            for (int j = i; j < N; j++) {
                int lo = sorted[i], hi = sorted[j];
                if (canRemoveQ(A, K, Q, lo, hi)) {
                    ans = Math.min(ans, hi - lo);
                }
            }
        }
        System.out.println(ans);
    }

    static boolean canRemoveQ(int[] A, int K, int Q, int lo, int hi) {
        ArrayList<Integer> arr = new ArrayList<>();
        for (int x : A) arr.add(x);
        int removed = 0;
        int i = 0;
        while (i < arr.size() && removed < Q) {
            if (arr.get(i) < lo) { i++; continue; }
            // try window starting at i
            if (i + K > arr.size()) break;
            boolean valid = true;
            int target = -1;
            for (int j = i; j < i + K; j++) {
                if (arr.get(j) < lo) { valid = false; break; }
                if (arr.get(j) <= hi && target == -1) target = j;
            }
            if (valid && target != -1) { arr.remove(target); removed++; }
            else i++;
        }
        return removed >= Q;
    }
}

