public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int K = fs.nextInt();
        int Q = fs.nextInt();

        int[] A = new int[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextInt();

        int[] sortedVals = A.clone();
        Arrays.sort(sortedVals);

        int ans = Integer.MAX_VALUE;

        for (int baseIdx = 0; baseIdx < N; baseIdx++) {
            int threshold = sortedVals[baseIdx];

            ArrayList<Integer> candidates = new ArrayList<>();

            int i = 0;
            while (i < N) {
                if (A[i] < threshold) {
                    i++;
                    continue;
                }

                ArrayList<Integer> segment = new ArrayList<>();
                while (i < N && A[i] >= threshold) {
                    segment.add(A[i]);
                    i++;
                }

                int len = segment.size();
                if (len >= K) {
                    Collections.sort(segment);
                    int take = len - K + 1;
                    for (int t = 0; t < take; t++) {
                        candidates.add(segment.get(t));
                    }
                }
            }

            if (candidates.size() < Q) continue;

            Collections.sort(candidates);
            ans = Math.min(ans, candidates.get(Q - 1) - threshold);
        }

        System.out.println(ans);
    }
